/bin/bash -lc "npm test && node --input-type=module - <<'NODE'
import path from 'node:path';
import { requestedFile } from './src/files.js';
for (const name of ['report.txt','../../etc/passwd','/etc/passwd','']) {
  try { console.log(JSON.stringify(name), '=>', requestedFile(name)); }
  catch (e) { console.log(JSON.stringify(name), '=> throws', e.code, e.message); }
}
try { console.log('null =>', requestedFile(null)); } catch (e) { console.log('null => throws', e.code, e.message); }
console.log('join absolute check:', path.join('/srv/customer-files','/etc/passwd'));
NODE
printf '\\n--- git status ---\\n'; git status --short"

